class Opts:
    pass


def play(stdscr, opts):
    curses.curs_set(0)
    stdscr.nodelay(True)
    stdscr.keypad(True)
    if hasattr(curses, "meta"):
        try:
            stdscr.meta(True)
        except curses.error:
            pass
    theme = Theme(stdscr, color=not opts.no_color, force_ascii=opts.ascii)
    game = Game(opts)
    show_help = False
    size = stdscr.getmaxyx()
    min_y, min_x = 20, 44
    fps = 60.0
    frame = 1.0 / fps
    last = time.monotonic()

    while True:
        t0 = time.monotonic()
        ch = stdscr.getch()
        while ch != -1:
            if show_help:
                show_help = False
            else:
                action = game.handle_key(ch)
                if action == "quit":
                    return
                if action == "help":
                    show_help = True
            ch = stdscr.getch()

        if stdscr.getmaxyx() != size:
            size = stdscr.getmaxyx()
            curses.update_lines_cols()

        if size[0] < min_y or size[1] < min_x:
            stdscr.erase()
            mid = size[1] // 2
            for i, msg in enumerate((
                "terminal too small",
                "need at least %d x %d - resize the window" % (min_x, min_y),
                "",
                "q to quit",
            )):
                try:
                    stdscr.addstr(max(0, size[0] // 2 - 2 + i),
                                  max(0, mid - len(msg) // 2), msg, curses.A_BOLD)
                except curses.error:
                    pass
            stdscr.refresh()
            curses.napms(80)
            continue

        game.update(min(0.25, t0 - last))
        last = t0
        if show_help:
            game.draw(stdscr, theme, size)
            game.draw_help(stdscr, theme, size)
        else:
            game.draw(stdscr, theme, size)
        spent = time.monotonic() - t0
        if spent < frame:
            curses.napms(int((frame - spent) * 1000) + 1)


def main(argv=None):
    opts = parse_args(argv)
    if opts.seed is not None:
        random.seed(opts.seed)
    opts.hold = not opts.no_hold
    opts.shadow = not opts.no_shadow
    opts.color = not opts.no_color
    try:
        curses.wrapper(play, opts)
    except KeyboardInterrupt:
        pass
    print("thanks for playing")
    return 0


if __name__ == "__main__":
    sys.exit(main())

