def note_key(self, direction):
    """Called when a movement key event arrives (first press or terminal repeat)."""
    self.keys_held[direction] = time.monotonic()
    if self.repeat["dir"] != direction:
        self.repeat = {"dir": direction, "timer": 0.0, "delay": 0.0}
        if direction == "down":
            self.soft_drop()
        else:
            self.move(-1 if direction == "left" else 1)
    # repeats coming from the terminal itself are swallowed: our own DAS
    # generates the movement at a consistent rate.

def release_key(self, direction):
