#!/usr/bin/env python3
"""Headless tests for tetris.py - drives the game logic without a terminal.

Run with:  python3 -m unittest -v test_tetris   (or ./test_tetris.py)
"""

import curses
import random
import types
import unittest

import tetris
from tetris import (CLEAR_ANIM, COLS, HIDDEN, LOCK_DELAY, MAX_LOCK_RESETS,
                    MAX_LEVEL, ROWS, VIS_ROWS, Game, Piece, Theme, clear_rows,
                    collides, full_rows, ghost_y, gravity_interval,
                    level_for_lines, make_board)


def make_opts(**kw):
    opts = types.SimpleNamespace(
        next=3, start_level=1, hold=True, shadow=True, color=False,
        ascii=False, no_color=True)
    for k, v in kw.items():
        setattr(opts, k, v)
    return opts


def new_game(seed=1234, **kw):
    opts = make_opts(**kw)
    random.seed(seed)
    return Game(opts)


def drop_clear(g, kind, x, y=0, rot=0):
    """Hard-drop a piece and return the score earned by line clears alone."""
    piece = Piece(kind, x=x, y=y, rot=rot)
    dist = ghost_y(g.board, piece) - piece.y
    g.piece = piece
    before = g.score
    g.hard_drop()
    return g.score - before - tetris.HARD_DROP_SCORE * dist


def fill_row(board, y, except_cols=()):
    for x in range(COLS):
        board[y][x] = 0 if x in except_cols else 7


def place(board, kind, rot, x, y):
    """Lock a piece directly onto the board (test setup helper)."""
    piece = Piece(kind, x=x, y=y, rot=rot)
    for px, py in piece.cells():
        if 0 <= py < ROWS and 0 <= px < COLS:
            board[py][px] = tetris.PIECE_COLOR[kind]
    return piece


class FakeWindow:
    """Records addstr/addch calls, enforces screen bounds like curses does."""

    def __init__(self, y, x):
        self.size = (y, x)
        self.written = []

    def getmaxyx(self):
        return self.size

    def erase(self):
        self.written = []

    def refresh(self):
        pass

    def noutrefresh(self):
        pass

    def addstr(self, y, x, text, attr=0):
        if y < 0 or y >= self.size[0] or x < 0 or x >= self.size[1]:
            raise curses.error("addstr out of bounds")
        if x + len(text) > self.size[1]:

            self.lock_piece()
    else:
        self.lock_timer = 0.0

# -- auto repeat (DAS) -------------------------------------------------
def update_repeat(self, dt):
    """Auto-repeat for held movement keys, driven by the game clock so it
    pauses with the game and behaves identically on every machine."""
    for direction in ("left", "right", "down"):
        if self.clock - self.keys_held[direction] > REPEAT_SILENCE:
            if self.repeat["dir"] == direction:
                self.repeat["dir"] = None
    if self.repeat["dir"] is None:
        return
    d = self.repeat["dir"]
    self.repeat["delay"] += dt
    if self.repeat["delay"] < DAS_DELAY:
        return
    self.repeat["timer"] += dt
    rate = SOFT_RATE if d == "down" else DAS_RATE
    while self.repeat["timer"] >= rate:
        self.repeat["timer"] -= rate
        if d == "down":
            self.soft_drop()
        elif d == "left":
            self.move(-1)
        else:
            self.move(1)

def note_key(self, direction):
    """A movement key event arrived (first press or terminal auto-repeat).

    Movement is generated here on the first press and afterwards by our own
    auto-repeat; auto-repeats echoed by the terminal are ignored so the
    speed does not depend on terminal settings.
    """
    self.keys_held[direction] = self.clock
    if self.repeat["dir"] != direction:
        self.repeat = {"dir": direction, "timer": 0.0, "delay": 0.0}
        if direction == "down":
            self.soft_drop()

