def clean(b):
    t = b.decode("utf-8", "replace")
    t = re.sub(r"\x1b\][^\x07\x1b]*(\x07|\x1b\\)", "", t)
    t = re.sub(r"\x1b[=>]", "", t)
    t = re.sub(r"\x1b[\[\()?#;>!]*[0-9;]*[A-Za-z@]", "", t)
    return t

def screen(b, rows=30, cols=100):
    """Very small terminal emulator: cursor addressing over a grid."""
    t = b.decode("utf-8", "replace")
    grid = [[" "] * cols for _ in range(rows)]
    cy = cx = 0
    i = 0
    while i < len(t):
        c = t[i]
        if c == "\x1b":
            m = re.match(r"\x1b\[([0-9;]*)([A-Za-z])", t[i:])
            if m:
                params, cmd = m.group(1), m.group(2)
                nums = [int(x) for x in params.split(";") if x.isdigit()]
                if cmd == "H":
                    cy = (nums[0] - 1) if len(nums) > 0 else 0
                    cx = (nums[1] - 1) if len(nums) > 1 else 0
                elif cmd == "J":
                    grid = [[" "] * cols for _ in range(rows)]
                elif cmd == "m":
                    pass
                i += m.end()
                continue
            m2 = re.match(r"\x1b\][^\x07\x1b]*(\x07|\x1b\\)", t[i:])
            if m2:
                i += m2.end(); continue
            i += 1
            continue
        if c == "\n":
            cy += 1; cx = 0
        elif c == "\r":
            cx = 0
        elif c == "\b":
            cx = max(0, cx - 1)
        elif c == "\t":
            cx = (cx // 8 + 1) * 8
        else:
            if 0 <= cy < rows and 0 <= cx < cols:
                grid[cy][cx] = c
            cx += 1
            if cx >= cols:
                cx = cols - 1
        i += 1
    return "\n".join("".join(row).rstrip() for row in grid)

if __name__ == "__main__":
