class Piece:
    __slots__ = ("kind", "rot", "x", "y")

    def __init__(self, kind, x=None, y=None, rot=0):
        self.kind = kind
        self.rot = rot % 4
        w = len(SHAPES[kind][0])
        self.x = COLS // 2 - (w + 1) // 2 if x is None else x
        self.y = 0 if y is None else y

