# -- auto repeat (DAS) -------------------------------------------------
def update_repeat(self, dt):
    """Horizontal/vertical auto-repeat.

    Two worlds have to work: terminals that send repeats while a key is
    held (the common case) and terminals that only send the initial press.
    Repeats we see are applied one per event and suppress our own timer;
    if none show up, our delayed auto-repeat carries the movement instead.
    """
    d = self.repeat["dir"]
    if d is None:
        return
    if self.repeat["seen"] > 1:
        # the terminal is repeating for us: silence means the key is up
        if self.clock - self.repeat["last"] > REPEAT_SILENCE:
            self.repeat["dir"] = None
        return                      # otherwise its events do the moving
    if self.repeat["steps"] >= FALLBACK_STEPS:
        return
    self.repeat["delay"] += dt
    if self.repeat["delay"] < DAS_DELAY:
        return
    self.repeat["timer"] += dt
    rate = SOFT_RATE if d == "down" else DAS_RATE
    while self.repeat["timer"] >= rate and self.repeat["steps"] < FALLBACK_STEPS:
        self.repeat["timer"] -= rate
        self.repeat["steps"] += 1
        self._step(d)

def _step(self, direction):
    if direction == "down":
        self.soft_drop()
    else:
        self.move(-1 if direction == "left" else 1)

def note_key(self, direction):
    """A movement key event arrived: the first press, or a terminal repeat."""
    r = self.repeat
    if r["dir"] == direction:
        r["seen"] += 1

